// Bundled snapshot of the Flyway seed (generated by scripts/seed/gen-seed.mjs).
// Shown when the API is cold-starting or unreachable, so a portfolio visitor never sees a broken page.
import snapshot from "./demo-data.json";
import type { Category, ListingCard, ListingDetail, Page, SearchParams } from "../types";

export const demoCategories = snapshot.categories as Category[];
export const demoListings = snapshot.listings as unknown as ListingDetail[];

const toCard = (l: ListingDetail): ListingCard => ({
  id: l.id,
  title: l.title,
  city: l.city,
  district: l.district,
  dailyPrice: l.dailyPrice,
  deposit: l.deposit,
  coverUrl: l.coverUrl,
  category: l.category,
  ratingAvg: l.ratingAvg,
  reviewCount: l.reviewCount,
  hostId: l.hostId,
  hostName: l.hostName,
  status: l.status,
  createdAt: l.createdAt,
});

const fold = (s: string) => s.toLocaleLowerCase("az");

/** Same filters / sort / paging as GET /api/listings (date availability is unknown offline). */
export function demoSearch(p: SearchParams): Page<ListingCard> {
  let rows = demoListings.slice();
  if (p.q) {
    const q = fold(p.q.trim());
    rows = rows.filter((l) => fold(l.title).includes(q) || fold(l.description).includes(q));
  }
  if (p.category) rows = rows.filter((l) => l.category.slug === p.category);
  if (p.city) rows = rows.filter((l) => l.city === p.city);
  if (p.minPrice != null) rows = rows.filter((l) => l.dailyPrice >= p.minPrice!);
  if (p.maxPrice != null) rows = rows.filter((l) => l.dailyPrice <= p.maxPrice!);
  const sort = p.sort ?? "newest";
  rows.sort((a, b) => {
    if (sort === "price_asc") return a.dailyPrice - b.dailyPrice;
    if (sort === "price_desc") return b.dailyPrice - a.dailyPrice;
    if (sort === "rating") return b.ratingAvg - a.ratingAvg || b.reviewCount - a.reviewCount;
    return b.createdAt.localeCompare(a.createdAt);
  });
  const size = p.size ?? 12;
  const page = p.page ?? 0;
  return {
    content: rows.slice(page * size, page * size + size).map(toCard),
    page,
    size,
    totalElements: rows.length,
    totalPages: Math.max(1, Math.ceil(rows.length / size)),
  };
}

export function demoListing(id: number): ListingDetail | null {
  return demoListings.find((l) => l.id === id) ?? null;
}
